/**
 * Part 9 contract-drift binder (TypeScript side).
 *
 * Binds the committed cross-language manifest
 * (`rust-backend/fixtures/contracts/manifest.json`, generated by
 * `npm run contracts:generate` from these same live TS sources) to the
 * RUNNING TS code and the Next-side handler sources. Pairs with the Rust
 * binders (`crates/ruke-contracts/tests/manifest_drift.rs`,
 * `crates/ruke-websearch/tests/manifest_drift.rs`): every wire fact in the
 * ledger is asserted against real code on BOTH sides, so a rename, casing
 * change, omission-rule flip, or timeout change on either side fails a test.
 *
 * This suite never mutates the manifest; regeneration is
 * `npm run contracts:generate`, and the byte-drift gate is
 * `npm run contracts:check` (both also wired into the Part 9 command gate).
 */
import { readFileSync } from "node:fs";
import path from "node:path";
import { describe, expect, it } from "vitest";

import { MODE_FENCE, MODE_SKILL, RENDERER_MODES } from "@/lib/decision/types";
import { extractInterface } from "../../rust-backend/scripts/contractParse.mjs";

const ROOT = process.cwd(); // vitest runs at the repo root
const read = (rel: string) => readFileSync(path.join(ROOT, rel), "utf8");

const manifest = JSON.parse(read("rust-backend/fixtures/contracts/manifest.json"));

// Rust chat-side header emitter (headers.rs) used for cross-side spelling checks.
const rustHeadersSrc = read(path.join("rust-backend", "crates", "ruke-server", "src", "chat", "headers.rs"));
const rustStagesSrc = read(path.join("rust-backend", "crates", "ruke-contracts", "src", "stages.rs"));

describe("contract manifest (Part 9 drift protection)", () => {
  it("decisionModes ledger matches the live TS runtime tables exactly", () => {
    const modes = manifest.decisionModes.order as (typeof RENDERER_MODES)[number][];
    expect(modes).toEqual([...RENDERER_MODES]);
    for (const mode of modes) {
      expect(manifest.decisionModes.skill[mode]).toBe(MODE_SKILL[mode]);
      expect(manifest.decisionModes.fence[mode]).toBe(MODE_FENCE[mode]);
    }
    // No extra/missing modes on either side of the ledger.
    expect(Object.keys(manifest.decisionModes.skill).sort()).toEqual([...RENDERER_MODES].sort());
    expect(Object.keys(manifest.decisionModes.fence).sort()).toEqual([...RENDERER_MODES].sort());
  });

  it("interface ledgers are still true of the live TS sources (manifest not stale vs TS)", () => {
    const cases: Array<[unknown, string, string]> = [
      [manifest.decisionRequest.fields, "lib/decision/types.ts", "export interface DecisionRequest"],
      [manifest.decisionEnvelope.fields, "lib/decision/types.ts", "export interface DecisionEnvelope"],
      [manifest.stageEvent.fields, "lib/types.ts", "export interface StageEvent"],
      [manifest.settings.fields, "lib/server/settings.ts", "interface SettingsShape"],
    ];
    for (const [ledger, file, decl] of cases) {
      // If the live TS interface drifts from the committed ledger, this
      // toEqual fails BEFORE any Rust code sees the change.
      expect(extractInterface(read(file), decl)).toEqual(ledger);
    }
  });

  it("omission-vs-null classes are populated and casing conventions hold (serialization parity)", () => {
    const envFields = manifest.decisionEnvelope.fields as Array<{ name: string; present: string; nullable: boolean }>;
    const reqFields = manifest.decisionRequest.fields as Array<{ name: string; present: string; nullable: boolean }>;
    // These exact classifications are what the Rust mirror must reproduce;
    // the Rust binder asserts them against actual serializer behavior.
    expect(envFields.filter((f) => f.present === "optional-omit-when-absent").map((f) => f.name))
      .toEqual(["lfm_input", "lfm_raw"]);
    expect(envFields.filter((f) => f.present === "always-present" && f.nullable).map((f) => f.name))
      .toEqual(["skill_to_load", "allowed_code_fence"]);
    const historyField = reqFields.find((f) => f.name === "conversationHistory");
    expect(historyField?.present).toBe("optional-omit-when-absent");
    expect(reqFields.filter((f) => f.present === "optional-omit-when-absent").map((f) => f.name))
      .toEqual(["conversationHistory"]);
    // The ENVELOPE (worker response wire JSON) is snake_case on both sides;
    // the Rust binder pins that against the actual serializer.
    for (const f of envFields) expect(f.name).toBe(f.name.toLowerCase());
    // The DECISION REQUEST leg is camelCase — and it really does cross the
    // language boundary: ruke-decision/src/engine.rs reads the JSON map by
    // these exact spellings. (historyField's existence is asserted above.)
    if (historyField) {
      expect(read(path.join("rust-backend", "crates", "ruke-decision", "src", "engine.rs")))
        .toContain(`"${historyField.name}"`);
    }
  });

  it("internal RPC ledger matches the live Next-side handlers", () => {
    const rpc = manifest.rpc;
    const routes: Record<string, string> = {
      browserRead: "app/api/internal/browser-read/route.ts",
      youtubeEvidence: "app/api/internal/youtube-evidence/route.ts",
      mediaTranscript: "app/api/internal/media-transcript/route.ts",
    };
    for (const [key, file] of Object.entries(routes)) {
      const src = read(file);
      expect(src).toContain(rpc.secretHeader); // secret header spelling on the producer side
      for (const body of Object.values(rpc[key].errors as Record<string, string>)) {
        // Error bodies are exact user-visible strings; the Rust client and
        // vitest golden replays pin the same literals byte-for-byte.
        expect(src).toContain(`"${body}"`);
      }
      for (const field of rpc[key].requestFields as string[]) {
        expect(src).toContain(field);
      }
      // The Rust client paths (bound to the manifest in the Rust test) must
      // correspond to real Next route files.
      expect(file).toContain(rpc[key].path.replace("/api/internal/", ""));
    }
    // browser-read response ledger: every camelCase key is produced by the
    // live extractor (the Rust consumer pins the same set via deny_unknown_fields).
    const extractorSrc = read("lib/web-search/extractor.ts");
    for (const field of rpc.browserRead.responseFields) {
      expect(extractorSrc).toContain(field);
    }
    // media-transcript response keys are produced by its own route.
    for (const field of rpc.mediaTranscript.responseFields) {
      expect(read(routes.mediaTranscript)).toContain(field);
    }
  });

  it("supervisor env ledger names match the actual handoff (and rustProxy arms off the switch)", () => {
    const sup = read("scripts/dev-supervisor.mjs");
    for (const envName of Object.values(manifest.rpc.env as Record<string, string>)) {
      expect(sup).toContain(envName);
    }
    // lib/server/rustProxy.ts is the TS arming consumer of the switch:
    const proxy = read("lib/server/rustProxy.ts");
    expect(proxy).toContain(manifest.rpc.env.nextArmSwitch);
    expect(proxy).toContain(manifest.rpc.env.backendPort);
  });

  it("header ledger names match on BOTH sides (case-insensitively, per HTTP field rules)", () => {
    // HTTP field names are case-insensitive: the Rust http crate FORCES the
    // lowercase canonical form (HeaderName::from_static), while the TS route
    // writes X-Used-Skill/X-Web-Citations/X-Search-Gate in PascalCase. The
    // manifest ledger keeps the lowercase canonical spelling; renames (not
    // case restyles) are what this binder catches on either side.
    const names = (manifest.headers as Array<{ name: string }>).map((h) => h.name);
    const chatTs = read("app/api/chat/route.ts").toLowerCase();
    const rustHeaders = rustHeadersSrc.toLowerCase();
    for (const h of ["x-decision-mode", "x-used-skill", "x-web-citations", "x-search-gate"]) {
      expect(names).toContain(h); // ledger canonical spelling
      expect(chatTs).toContain(h); // TS chat route emits it
      expect(rustHeaders).toContain(h); // Rust chat route emits it
    }
    expect(names).toContain(manifest.rpc.secretHeader);
    for (const n of names) expect(n).toBe(n.toLowerCase()); // ledger itself is canonical-lowercase
  });

  it("secret is never logged in the TS seam (Rule 17 scan)", () => {
    const files = [
      "lib/server/rustProxy.ts",
      "app/api/internal/browser-read/route.ts",
      "app/api/internal/youtube-evidence/route.ts",
      "app/api/internal/media-transcript/route.ts",
    ];
    for (const file of files) {
      const lines = read(file).split("\n");
      for (let i = 0; i < lines.length; i++) {
        const call = lines[i].match(/console\.\w+\((.*)\)/);
        if (!call) continue;
        // Strip single-line string literals (static text mentioning the word
        // "secret" is fine) then flag any bare `secret` IDENTIFIER reaching a
        // log call — that is the value-leak shape. Templates with ${...} are
        // kept so interpolated leaks are caught.
        const args = call[1].replace(/"(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*'|`[^`$]*`/g, '""');
        if (/\bsecret\b/i.test(args)) {
          throw new Error(`${file}:${i + 1} logs near the secret value: ${lines[i].trim()}`);
        }
      }
    }
  });

  it("SSE frame keys and the honest-502 body match the ledger on both sides", () => {
    const chatTs = read("app/api/chat/route.ts");
    for (const key of [manifest.sseFrames.stageFrameKey, manifest.sseFrames.errorFrameKey]) {
      expect(chatTs).toContain(key); // TS route frames ({ ruke_stage: … })
      expect(rustStagesSrc).toContain(`"${key}"`); // Rust json! frame helpers
    }
    expect(manifest.sseFrames.doneMarker).toBe("[DONE]");
    const proxy = read("lib/server/rustProxy.ts");
    // Honest-502 body: the manifest's "<base>" placeholder is a template
    // interpolation in the proxy, so bind the literal prefix.
    expect(proxy).toContain(manifest.proxyFailureContract.unreachableBody.error.split("<base>")[0]);
    expect(manifest.proxyFailureContract.status).toBe(502);
  });
});
